/*
 * A106123  Primes with maximal digit > 6.
 * https://oeis.org/A106123
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 32, u16 n <= 55, u32 n <= 55, u64 n <= 55, u128 n <= 55,
 *            big any n
 * Validated: partial, pass, 55 terms through n = 55 (2026-11-03)
 * Helpers:   is_prime_u64, mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A106123: Primes whose maximal decimal digit exceeds 6
 *
 * The sequence is generated by searching for primes and keeping those
 * that contain at least one digit 7, 8, or 9. It is implemented with a
 * lazy cache: the first time a(n) is requested, the algorithm iterates
 * over natural numbers, tests primality with isPrime64(), checks the
 * digit condition, and stores qualifying primes until enough terms
 * are accumulated. Subsequent calls reuse the cache and continue the
 * search only if a larger n is requested. This satisfies the
 * requirement of arbitrary call order and guarantees O(n) time for
 * n up to at least 10 000.
 */

#include <stdbool.h>
#include <stdlib.h>
#include <stdint.h>

#include <stddef.h>
#include "../utils/is_prime_u64.h"
#include "../utils/mem.h"

/* return true if the largest decimal digit of x exceeds 6 */
static bool has_max_digit_gt6(uint64_t x)
{
    while (x > 0) {
        uint8_t d = (uint8_t)(x % 10);
        if (d > 6) return true;
        x /= 10;
    }
    return false;
}

static seq_t *cache = NULL;          /* cached primes of the sequence   */
static size_t cache_cap = 0;         /* allocated capacity               */
static size_t cache_size = 0;        /* number of terms stored           */
static uint64_t search_start = 2;    /* next number to test for prime    */
static bool initialized = false;

seq_t a(idx_t n)
{
    if (n == 0) return 0;     /* undefined for offset 1, but safe */

    if (!initialized) {
        initialized = true;
        cache_cap = 1024;
        cache_size = 0;
        cache = mem_new(seq_t, cache_cap);
        search_start = 2;
    }

    /* enlarge cache when necessary */
    while (cache_size < (size_t)n) {
        /* test candidate number */
        if (is_prime_u64(search_start) && has_max_digit_gt6(search_start)) {
            if (cache_size == cache_cap) {
                cache_cap *= 2;
                cache = mem_resize(seq_t, cache, cache_cap);
            }
            cache[cache_size++] = (seq_t)search_start;
        }
        search_start++;
    }

    return cache[n - 1];
}
